//! End-to-end MicroPDF417 (ISO/IEC 24728) tests.
//!
//! Two things are checked:
//!
//! 1. **Independent reference vectors.** The expected module bitmaps are generated by
//!    the (BSD-3-Clause) zint project, version 2.16.0, via
//!    `zint -b MICROPDF417 -d <DATA> --cols <N> --scale 1 -o out.svg`, reading the dark
//!    modules straight out of zint's rendered SVG vector path (the SVG is used rather
//!    than `--dump` because `--dump`'s byte-packing leaves the trailing stop module of
//!    a non-byte-aligned row unreliable). zint's MicroPDF417 output is itself
//!    cross-checked against BWIPP in its own test suite, so this pins our encoder to an
//!    external implementation of the standard across all four column configurations.
//!
//! 2. **Lossless round-trip.** `encode → decode → re-encode` must reproduce the exact
//!    segments, metadata and module matrix across Text/Byte/Numeric compaction and
//!    every column count.
#![cfg(all(feature = "decode", feature = "encode", feature = "pdf417"))]

use anyd::codes::pdf417::{MicroPdf417Decoder, MicroPdf417Encoder};
use anyd::output::{BitMatrix, Encoding};
use anyd::segment::Segment;
use anyd::traits::{Decode, Encode};

/// Reference bitmaps from zint 2.16.0. Each entry is `(data, columns, rows)` where
/// every row string is `width` characters of `0`/`1`, most-significant module first.
#[allow(clippy::type_complexity)]
const REFERENCE: &[(&str, usize, &[&str])] = &[
    // zint 2.16.0 SVG:  zint -b MICROPDF417 -d "A" --cols 1  (11 rows x 38)
    (
        "A",
        1,
        &[
            "11001000101000011000110010011100110101",
            "11101000101111101011101111011110110101",
            "11101100101100011111001001011110010101",
            "11001100101000011000110010011100010101",
            "11011100101111101000101100011000010101",
            "11011110101100010010111110011000110101",
            "11001110101001111011110100011000100101",
            "11101110101111011001100100011100100101",
            "11100110101001111110011101011110100101",
            "11110110101110001010111000011110101101",
            "11110010101011111100010011011110101001",
        ],
    ),
    // zint 2.16.0 SVG:  zint -b MICROPDF417 -d "ABCDEFGH" --cols 2  (8 rows x 55)
    (
        "ABCDEFGH",
        2,
        &[
            "1100100010100001100011001001111010101111000011001000101",
            "1110100010110101111110111101111101000100110011101000101",
            "1110110010101101100111100001100011111001001011101100101",
            "1100110010100001100011001001000011000110010011001100101",
            "1101110010100011011111101101111001000001001011011100101",
            "1101111010110011110100011001000111100001010011011110101",
            "1100111010100000101100110001110111001000001011001110101",
            "1110111010111110011000101001110100110100000011101110101",
        ],
    ),
    // zint 2.16.0 SVG:  zint -b MICROPDF417 -d "Wikipedia" --cols 3  (6 rows x 82)
    (
        "Wikipedia",
        3,
        &[
            "1100100010100001100011001001011001110110011101110011001110010001001110011001000101",
            "1110100010110010111100001101001001110111111010001011101100101110001000011101000101",
            "1110110010110000111010111001001101110101100001001110001000010001001111011101100101",
            "1100110010110000100010001101000101110110011010000010001001100111011000011001100101",
            "1101110010100010000111101001000100110101111101100111101101101111000001011011100101",
            "1101111010100011010001110001000110110101110000100011001010100000111100011011110101",
        ],
    ),
    // zint 2.16.0 SVG:  zint -b MICROPDF417 -d "123456789012" --cols 4  (4 rows x 99)
    (
        "123456789012",
        4,
        &[
            "110100111010111111010011000111111010101110001001110110100110001111101001111101001100111011010010001",
            "110100110010000010101111000101000010011110001001110100110001111100100101100011111001001011010110001",
            "110100010011100011000100110101110111101100001001100100100011001111011101000111011110110011010111001",
            "110100011011100010110000010111100101000000101001100110111111001110010101111110111000101011010111101",
        ],
    ),
];

/// Render a symbol's matrix, sampling the top module of each stacked codeword row into
/// a bit string per row (the encoder renders every codeword row several modules tall).
fn row_strings(matrix: &BitMatrix, num_rows: usize) -> Vec<String> {
    let step = matrix.height() / num_rows;
    (0..num_rows)
        .map(|r| {
            let y = r * step;
            (0..matrix.width())
                .map(|x| if matrix.get(x, y) { '1' } else { '0' })
                .collect()
        })
        .collect()
}

#[test]
fn matches_zint_reference_bitmaps() {
    let enc = MicroPdf417Encoder::new();
    for &(data, cols, expected) in REFERENCE {
        // Match zint's high-level mode choice: numeric compaction for all-digit data,
        // otherwise Text compaction.
        let segment = if data.bytes().all(|b| b.is_ascii_digit()) {
            Segment::numeric(data.as_bytes().to_vec())
        } else {
            Segment::alphanumeric(data.as_bytes().to_vec())
        };
        let symbol = enc
            .build_sized(vec![segment], Some(cols))
            .unwrap_or_else(|e| panic!("build {data:?} cols {cols}: {e:?}"));
        let Encoding::Matrix(m) = enc.encode(&symbol).unwrap() else {
            panic!("expected a matrix");
        };
        let got = row_strings(&m, expected.len());
        assert_eq!(
            got.len(),
            expected.len(),
            "row count differs for {data:?} cols {cols}"
        );
        for (i, (g, e)) in got.iter().zip(expected).enumerate() {
            assert_eq!(
                g, e,
                "row {i} differs from zint for {data:?} cols {cols}\n got: {g}\n exp: {e}"
            );
        }
    }
}

/// Assert exact round-trip: decode recovers the segments and metadata, and re-encoding
/// reproduces a byte-identical matrix.
fn assert_lossless(segments: Vec<Segment>, columns: Option<usize>) {
    let enc = MicroPdf417Encoder::new();
    let symbol = enc.build_sized(segments.clone(), columns).unwrap();
    let encoding = enc.encode(&symbol).unwrap();

    let decoded = MicroPdf417Decoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, symbol.segments, "segments differ");
    assert_eq!(decoded.meta, symbol.meta, "meta differs");

    let re = enc.encode(&decoded).unwrap();
    assert_eq!(encoding, re, "re-encode is not identical");
}

#[test]
fn roundtrip_text_all_columns() {
    for cols in 1..=4 {
        assert_lossless(
            vec![Segment::alphanumeric(b"Hello, MicroPDF417!".to_vec())],
            Some(cols),
        );
    }
}

#[test]
fn roundtrip_numeric_all_columns() {
    for cols in 1..=4 {
        assert_lossless(
            vec![Segment::numeric(b"9876543210123456".to_vec())],
            Some(cols),
        );
    }
}

#[test]
fn roundtrip_byte_all_columns() {
    for cols in 1..=4 {
        assert_lossless(
            vec![Segment::byte(vec![0u8, 1, 2, 3, 127, 128, 254, 255])],
            Some(cols),
        );
    }
}

#[test]
fn roundtrip_mixed_segments_autosize() {
    assert_lossless(
        vec![
            Segment::alphanumeric(b"PART".to_vec()),
            Segment::numeric(b"00427".to_vec()),
            Segment::byte(vec![0xDE, 0xAD, 0xBE, 0xEF]),
        ],
        None,
    );
}

#[test]
fn autosize_grows_with_data() {
    let enc = MicroPdf417Encoder::new();
    let small = enc.build_text("Hi").unwrap();
    let large = enc
        .build_text("The quick brown fox jumps over the lazy dog 0123456789")
        .unwrap();
    let Encoding::Matrix(sm) = enc.encode(&small).unwrap() else {
        panic!("matrix");
    };
    let Encoding::Matrix(lm) = enc.encode(&large).unwrap() else {
        panic!("matrix");
    };
    assert!(
        sm.width() * sm.height() <= lm.width() * lm.height(),
        "larger payload should not yield a smaller symbol"
    );
    // Both must still round-trip.
    assert_eq!(
        MicroPdf417Decoder::new().decode_matrix(&lm).unwrap().text(),
        large.text()
    );
}

use anyd::codes::pdf417::{EcLevel, Pdf417Meta, Pdf417Variant};
use anyd::error::Error;
use anyd::symbol::{Symbol, SymbolMeta};
use anyd::symbology::Symbology;

/// The 34 size variants of ISO/IEC 24728 in table order: `(columns, rows,
/// error-correction codewords)`.
const VARIANTS: [(usize, usize, usize); 34] = [
    (1, 11, 7),
    (1, 14, 7),
    (1, 17, 7),
    (1, 20, 8),
    (1, 24, 8),
    (1, 28, 8),
    (2, 8, 8),
    (2, 11, 9),
    (2, 14, 9),
    (2, 17, 10),
    (2, 20, 11),
    (2, 23, 13),
    (2, 26, 15),
    (3, 6, 12),
    (3, 8, 14),
    (3, 10, 16),
    (3, 12, 18),
    (3, 15, 21),
    (3, 20, 26),
    (3, 26, 32),
    (3, 32, 38),
    (3, 38, 44),
    (3, 44, 50),
    (4, 4, 8),
    (4, 6, 12),
    (4, 8, 14),
    (4, 10, 16),
    (4, 12, 18),
    (4, 15, 21),
    (4, 20, 26),
    (4, 26, 32),
    (4, 32, 38),
    (4, 38, 44),
    (4, 44, 50),
];

/// Module width of a symbol with the given number of data columns.
const WIDTHS: [usize; 5] = [0, 38, 55, 82, 99];

/// Builds a segment of the given length.
type MakeSegment = fn(usize) -> Segment;

fn micro_symbol(segments: Vec<Segment>, variant: usize) -> Symbol {
    let (columns, rows, _) = VARIANTS[variant];
    Symbol::new(
        Symbology::MicroPdf417,
        segments,
        SymbolMeta::Pdf417(Pdf417Meta {
            rows,
            columns,
            ec_level: EcLevel::new(0).unwrap(),
            variant: Pdf417Variant::Micro(variant as u8),
        }),
    )
}

/// Every size variant, filled to its last data codeword, has the tabulated geometry
/// and round-trips; one codeword more is a capacity error. (Text compaction: a latch
/// plus one codeword per two characters.)
#[test]
fn every_variant_roundtrips_at_capacity() {
    let enc = MicroPdf417Encoder::new();
    let dec = MicroPdf417Decoder::new();
    for (variant, &(columns, rows, ec)) in VARIANTS.iter().enumerate() {
        let data_codewords = columns * rows - ec;
        let full: Vec<u8> = (0..2 * (data_codewords - 1))
            .map(|i| b'A' + (i % 26) as u8)
            .collect();

        let symbol = micro_symbol(vec![Segment::alphanumeric(full.clone())], variant);
        let encoding = enc.encode(&symbol).unwrap();
        let Encoding::Matrix(m) = &encoding else {
            panic!("expected a matrix");
        };
        assert_eq!(m.width(), WIDTHS[columns], "variant {variant}");
        assert_eq!(m.height() % rows, 0, "variant {variant}");
        let decoded = dec.decode(&encoding).unwrap();
        assert_eq!(decoded, symbol, "variant {variant}");
        assert_eq!(enc.encode(&decoded).unwrap(), encoding, "variant {variant}");

        // A nearly empty symbol of the same variant pads and round-trips as well.
        let sparse = micro_symbol(vec![Segment::numeric(b"7".to_vec())], variant);
        let encoding = enc.encode(&sparse).unwrap();
        assert_eq!(dec.decode(&encoding).unwrap(), sparse, "variant {variant}");

        let mut over = full;
        over.push(b'Z');
        let err = enc
            .encode(&micro_symbol(vec![Segment::alphanumeric(over)], variant))
            .unwrap_err();
        assert!(matches!(err, Error::Capacity { .. }), "variant {variant}");
    }
}

/// The symbology maxima of ISO/IEC 24728 — 250 text characters, 366 digits, 150
/// bytes — fit the largest variant; one more is a capacity error, as is anything
/// past the tallest symbol of a pinned column count.
#[test]
fn capacity_boundaries() {
    let enc = MicroPdf417Encoder::new();
    let cases: [(MakeSegment, [usize; 4]); 3] = [
        (|n| Segment::alphanumeric(vec![b'K'; n]), [38, 72, 162, 250]),
        (|n| Segment::numeric(vec![b'3'; n]), [55, 105, 237, 366]),
        (|n| Segment::byte(vec![0xC3; n]), [22, 43, 97, 150]),
    ];
    for (make, maxima) in cases {
        for (i, &max) in maxima.iter().enumerate() {
            let columns = i + 1;
            assert_lossless(vec![make(max)], Some(columns));
            let err = enc
                .build_sized(vec![make(max + 1)], Some(columns))
                .unwrap_err();
            assert!(matches!(err, Error::Capacity { .. }), "{columns} columns");
        }
        assert_lossless(vec![make(maxima[3])], None);
        for over in [maxima[3] + 1, maxima[3] + 9, 5000] {
            let err = enc.build(vec![make(over)]).unwrap_err();
            assert!(matches!(err, Error::Capacity { .. }), "{over}");
        }
    }
    for columns in [0, 5, 99] {
        assert!(
            enc.build_sized(vec![Segment::numeric(b"1".to_vec())], Some(columns))
                .is_err(),
            "{columns} columns"
        );
    }
    // No data at all is the smallest symbol, all padding.
    assert_lossless(Vec::new(), None);
}

/// Each variant repairs `(k - 2) / 2` unreadable codewords anywhere in the symbol,
/// `k` being its error-correction codeword count.
#[test]
fn every_variant_corrects_damaged_codewords() {
    let enc = MicroPdf417Encoder::new();
    let dec = MicroPdf417Decoder::new();
    let mut rng = anyd::transform::Rng::new(0x24728);
    for (variant, &(columns, rows, ec)) in VARIANTS.iter().enumerate() {
        let symbol = micro_symbol(vec![Segment::alphanumeric(b"Ab;".to_vec())], variant);
        let Encoding::Matrix(clean) = enc.encode(&symbol).unwrap() else {
            panic!("expected a matrix");
        };
        let row_height = clean.height() / rows;
        let cells = columns * rows;
        let mut hit = vec![false; cells];
        let mut left = (ec - 2) / 2;
        while left > 0 {
            let cell = (rng.next_u64() % cells as u64) as usize;
            if !hit[cell] {
                hit[cell] = true;
                left -= 1;
            }
        }
        let mut m = clean.clone();
        for (cell, _) in hit.iter().enumerate().filter(|(_, h)| **h) {
            let (row, col) = (cell / columns, cell % columns);
            // Left RAP (10), earlier columns (17 each), and the centre RAP (10) that
            // precedes the right half of 3- and 4-column symbols.
            let mut x0 = 10 + 17 * col;
            if (columns == 3 && col >= 1) || (columns == 4 && col >= 2) {
                x0 += 10;
            }
            for x in x0..x0 + 17 {
                for y in row * row_height..(row + 1) * row_height {
                    m.set(x, y, false);
                }
            }
        }
        let decoded = dec
            .decode(&Encoding::Matrix(m))
            .unwrap_or_else(|e| panic!("variant {variant}: {e:?}"));
        assert_eq!(decoded, symbol, "variant {variant}");
    }
}

/// The parameter and input error paths of the public API.
#[test]
fn rejects_bad_parameters_and_input() {
    let enc = MicroPdf417Encoder::new();
    let dec = MicroPdf417Decoder::new();
    let seg = || vec![Segment::alphanumeric(b"A".to_vec())];
    let with_meta =
        |meta: Pdf417Meta| Symbol::new(Symbology::MicroPdf417, seg(), SymbolMeta::Pdf417(meta));
    let good = Pdf417Meta {
        rows: 11,
        columns: 1,
        ec_level: EcLevel::new(0).unwrap(),
        variant: Pdf417Variant::Micro(0),
    };
    assert!(enc.encode(&with_meta(good.clone())).is_ok());

    // Metadata that names no variant, or contradicts the one it names, describes no
    // symbol (and could not come back from a decode unchanged).
    let bad_metas = [
        Pdf417Meta {
            variant: Pdf417Variant::Micro(34),
            ..good.clone()
        },
        Pdf417Meta {
            variant: Pdf417Variant::Micro(255),
            ..good.clone()
        },
        Pdf417Meta {
            variant: Pdf417Variant::Standard,
            ..good.clone()
        },
        Pdf417Meta {
            rows: 14,
            ..good.clone()
        },
        Pdf417Meta {
            columns: 2,
            ..good.clone()
        },
        Pdf417Meta {
            ec_level: EcLevel::new(3).unwrap(),
            ..good.clone()
        },
    ];
    for meta in bad_metas {
        let err = enc.encode(&with_meta(meta.clone())).unwrap_err();
        assert!(matches!(err, Error::InvalidParameter { .. }), "{meta:?}");
    }
    let mut other = with_meta(good.clone());
    other.symbology = Symbology::Pdf417;
    assert!(matches!(
        enc.encode(&other),
        Err(Error::InvalidParameter { .. })
    ));
    // ...and the standard encoder refuses a MicroPDF417 variant in turn.
    let mut standard = with_meta(Pdf417Meta {
        rows: 10,
        columns: 3,
        ..good.clone()
    });
    standard.symbology = Symbology::Pdf417;
    assert!(matches!(
        anyd::codes::pdf417::Pdf417Encoder::new().encode(&standard),
        Err(Error::InvalidParameter { .. })
    ));
    let bare = Symbol::new(Symbology::MicroPdf417, seg(), SymbolMeta::Generic);
    assert!(matches!(
        enc.encode(&bare),
        Err(Error::InvalidParameter { .. })
    ));
    // Unencodable segment content.
    assert!(enc.build(vec![Segment::numeric(b"1x".to_vec())]).is_err());
    assert!(enc.build(vec![Segment::byte(Vec::new())]).is_err());

    // Decoder input that cannot be a MicroPDF417 grid.
    let linear = Encoding::Linear(anyd::output::LinearPattern {
        modules: vec![true, false, true],
        quiet_zone: 1,
    });
    assert!(matches!(
        dec.decode(&linear),
        Err(Error::Unsupported { .. })
    ));
    for (width, height) in [
        (0, 0),
        (37, 22),
        (56, 16),
        (38, 21),
        (38, 24),
        (99, 6),
        (82, 90),
    ] {
        let m = BitMatrix::new(width, height, 1);
        assert!(dec.decode_matrix(&m).is_err(), "{width}x{height}");
    }
    // A blank grid of valid dimensions has no readable codeword at all.
    assert!(dec.decode_matrix(&BitMatrix::new(38, 22, 1)).is_err());
}

/// ECI escapes are part of the compaction layer MicroPDF417 shares with PDF417:
/// they round-trip, and a zint symbol carrying one reads (zint 2.16.0,
/// `zint -b MICROPDF417 --eci=26 -d é --dump`; 3 columns x 6 rows).
#[test]
fn eci_segments_roundtrip_and_read_from_zint() {
    assert_lossless(
        vec![
            Segment::eci(26),
            Segment::byte("é".as_bytes().to_vec()),
            Segment::eci(900),
            Segment::alphanumeric(b"Ab".to_vec()),
            Segment::eci(811_799),
        ],
        None,
    );

    let dump = [
        "C8 B1 C6 56 77 5C FA 08 45 91 4",
        "E8 BA 0C 52 77 A1 B2 FD 61 D1 4",
        "EC AC 11 D3 75 1B E2 76 1D D9 4",
        "CC B1 43 11 77 BD 12 71 D1 99 4",
        "DC B0 9C 91 37 90 8B E5 0D B9 4",
        "DE BA 7C 51 B6 FC CA 0E B1 BD 4",
    ];
    let width = 82;
    let mut m = BitMatrix::new(width, dump.len() * 2, 1);
    for (y, row) in dump.iter().enumerate() {
        // One hex digit per four modules, most-significant first.
        let nibbles: Vec<u32> = row.chars().filter_map(|c| c.to_digit(16)).collect();
        for x in 0..width {
            if (nibbles[x / 4] >> (3 - x % 4)) & 1 == 1 {
                m.set(x, 2 * y, true);
                m.set(x, 2 * y + 1, true);
            }
        }
    }
    let decoded = MicroPdf417Decoder::new().decode_matrix(&m).unwrap();
    assert_eq!(
        decoded.segments,
        vec![Segment::eci(26), Segment::byte("é".as_bytes().to_vec())]
    );
}
